SELECT TABLE_NAME, COLUMN_NAME, DATA_TYPE, COLUMN_TYPE FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = 'crypto_ai' AND ((TABLE_NAME = 'paper_position' AND COLUMN_NAME IN ('opened_at', 'closed_at')) OR (TABLE_NAME = 'trade_signal' AND COLUMN_NAME IN ('generated_at', 'candle_open_time')) OR (TABLE_NAME = 'candle' AND COLUMN_NAME = 'open_time') OR (TABLE_NAME = 'market_price_event' AND COLUMN_NAME IN ('observed_at', 'created_at'))) ORDER BY TABLE_NAME, COLUMN_NAME;